from collections import Counter
def components(g, exclude):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; shapes={}
    for r in range(H):
        for c in range(W):
            if g[r][c] in exclude or seen[r][c]: continue
            col=g[r][c]; stack=[(r,c)]; seen[r][c]=True; cells=[]
            while stack:
                rr,cc=stack.pop(); cells.append((rr,cc))
                for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=rr+dr,cc+dc
                    if 0<=a<H and 0<=b<W and not seen[a][b] and g[a][b]==col:
                        seen[a][b]=True; stack.append((a,b))
            if len(cells)>1: shapes.setdefault(col,set()).update(cells)
    return shapes
def solve4(g):
    H,W=len(g),len(g[0])
    cnt=Counter(c for row in g for c in row)
    noise=set()
    for c in cnt:
        if c==3: continue
        found=any(g[r][cc]==c and any(0<=r+dr<H and 0<=cc+dc<W and g[r+dr][cc+dc]==c for dr,dc in((1,0),(-1,0),(0,1),(0,-1))) for r in range(H) for cc in range(W))
        if not found: noise.add(c)
    shapes=components(g, noise|{3})
    out=[row[:] for row in g]
    for r in range(H):
        for c in range(W):
            if g[r][c] in noise:
                nb=[g[r+dr][c+dc] for dr,dc in((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<H and 0<=c+dc<W]
                nb=[x for x in nb if x not in noise]
                cntn=Counter(nb); top=cntn.most_common()
                best=top[0][1]; cands=[k for k,v in top if v==best]
                if len(cands)>1:
                    # tie: prefer a color that is a multi-cell shape
                    sh=[k for k in cands if k in shapes]
                    pick=sh[0] if sh else min(cands)
                else: pick=cands[0]
                out[r][c]=pick
    return out
